DUE_ITEMS_QUERY:
query DueItems($userId: ID!, $dueLimit: Int, $newLimit: Int, $itemType: String, $context: String) {
  dueItems(userId: $userId, dueLimit: $dueLimit, newLimit: $newLimit, itemType: $itemType, context: $context, includeLearningAhead: true) {
    id
    itemId
    itemType
    failureIndex
    card { source sourceCardId sourceNoteGuid direction prompt answer acceptedAnswers notes examples deck tags }
    wordRelation {
      id
      main {
        id
        word
        gramaticalCategories
        examples
        contexts
        level
        cefrLevel
        notes
        forms {
          gender
        }
      }
      translated {
        id
        word
        gramaticalCategories
        examples
        contexts
        level
        cefrLevel
        notes
        forms {
          gender
          plural
          past
          perfect
          imperativ
          irregularConjugations
          gramaticalCase
        }
      }
    }
    phraseRelation {
      id
      main {
        id
        phrase
        synonyms
        level
        cefrLevel
        contexts
      }
      translated {
        id
        phrase
        synonyms
      }
    }
    ease
    interval
    repetitions
    nextDueDate
    studyState scheduleVersion schedulerPhase learningQueue learnAheadSeconds
    reviewOptions { grade delaySeconds nextDueDate phase }
  }
}

